/* ============================================================
   ML CORE — every function below performs a genuine computation
   on the real arrays passed to it. Nothing here reads canned
   numbers; models are actually fit and actually evaluated.
   ============================================================ */
function mulberry32(seed) {
  return function () {
    seed |= 0; seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
function seededShuffle(arr, seed) {
  const rnd = mulberry32(seed);
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(rnd() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}
const mean = (arr) => arr.reduce((s, v) => s + v, 0) / arr.length;
const variance = (arr) => { const m = mean(arr); return mean(arr.map((v) => (v - m) ** 2)); };
const std = (arr) => Math.sqrt(variance(arr));
const median = (arr) => { const s = [...arr].sort((a, b) => a - b); const n = s.length; return n % 2 ? s[(n - 1) / 2] : (s[n / 2 - 1] + s[n / 2]) / 2; };
const modeOf = (arr) => { const c = {}; let best = arr[0], bc = 0; for (const v of arr) { c[v] = (c[v] || 0) + 1; if (c[v] > bc) { bc = c[v]; best = v; } } return best; };
function pearson(x, y) {
  const mx = mean(x), my = mean(y);
  let num = 0, dx = 0, dy = 0;
  for (let i = 0; i < x.length; i++) { const a = x[i] - mx, b = y[i] - my; num += a * b; dx += a * a; dy += b * b; }
  const den = Math.sqrt(dx * dy);
  return den === 0 ? 0 : num / den;
}
function argmax(arr) { let bi = 0, bv = -Infinity; for (let i = 0; i < arr.length; i++) if (arr[i] > bv) { bv = arr[i]; bi = i; } return bi; }
async function tick() { return new Promise((r) => setTimeout(r, 0)); }

function trainTestSplit(rows, testRatio = 0.25, seed = 42) {
  const shuffled = seededShuffle(rows, seed);
  const nTest = Math.max(1, Math.round(shuffled.length * testRatio));
  return { test: shuffled.slice(0, nTest), train: shuffled.slice(nTest) };
}
function splitXY(rows) { return { X: rows.map((r) => r.slice(0, -1)), y: rows.map((r) => r[r.length - 1]) }; }
function fitScaler(X) {
  const n = X[0].length; const means = new Array(n).fill(0), stds = new Array(n).fill(1);
  for (let j = 0; j < n; j++) { const col = X.map((r) => r[j]); means[j] = mean(col); stds[j] = std(col) || 1; }
  return { means, stds };
}
function applyScaler(X, scaler) { return X.map((r) => r.map((v, j) => (v - scaler.means[j]) / scaler.stds[j])); }

/* ---------- metrics ---------- */
function accuracyScore(yTrue, yPred) { let c = 0; for (let i = 0; i < yTrue.length; i++) if (yTrue[i] === yPred[i]) c++; return c / yTrue.length; }
function confusionMatrix(yTrue, yPred, nClasses) {
  const m = Array.from({ length: nClasses }, () => new Array(nClasses).fill(0));
  for (let i = 0; i < yTrue.length; i++) m[yTrue[i]][yPred[i]]++;
  return m;
}
function precisionRecallF1(yTrue, yPred, nClasses) {
  const cm = confusionMatrix(yTrue, yPred, nClasses);
  const per = [];
  for (let c = 0; c < nClasses; c++) {
    const tp = cm[c][c];
    const fp = cm.reduce((s, row, i) => (i === c ? s : s + row[c]), 0);
    const fn = cm[c].reduce((s, v, j) => (j === c ? s : s + v), 0);
    const precision = tp + fp === 0 ? 0 : tp / (tp + fp);
    const recall = tp + fn === 0 ? 0 : tp / (tp + fn);
    const f1 = precision + recall === 0 ? 0 : (2 * precision * recall) / (precision + recall);
    const support = cm[c].reduce((s, v) => s + v, 0);
    per.push({ precision, recall, f1, support });
  }
  const macro = { precision: mean(per.map((p) => p.precision)), recall: mean(per.map((p) => p.recall)), f1: mean(per.map((p) => p.f1)) };
  return { per, macro, cm };
}
const maeFn = (yTrue, yPred) => mean(yTrue.map((v, i) => Math.abs(v - yPred[i])));
const mseFn = (yTrue, yPred) => mean(yTrue.map((v, i) => (v - yPred[i]) ** 2));
const rmseFn = (yTrue, yPred) => Math.sqrt(mseFn(yTrue, yPred));
function r2Score(yTrue, yPred) {
  const m = mean(yTrue);
  const ssRes = yTrue.reduce((s, v, i) => s + (v - yPred[i]) ** 2, 0);
  const ssTot = yTrue.reduce((s, v) => s + (v - m) ** 2, 0);
  return ssTot === 0 ? 0 : 1 - ssRes / ssTot;
}
function rocCurve(yTrueBin, scores) {
  const thresholds = Array.from({ length: 26 }, (_, i) => i / 25);
  const P = yTrueBin.reduce((s, v) => s + v, 0), N = yTrueBin.length - P;
  return thresholds
    .map((t) => {
      let tp = 0, fp = 0;
      for (let i = 0; i < scores.length; i++) {
        const pred = scores[i] >= t ? 1 : 0;
        if (pred === 1 && yTrueBin[i] === 1) tp++;
        if (pred === 1 && yTrueBin[i] === 0) fp++;
      }
      return { threshold: +t.toFixed(2), tpr: P ? tp / P : 0, fpr: N ? fp / N : 0 };
    })
    .sort((a, b) => a.fpr - b.fpr);
}
function aucFromRoc(points) {
  let auc = 0;
  for (let i = 1; i < points.length; i++) auc += (points[i].fpr - points[i - 1].fpr) * (points[i].tpr + points[i - 1].tpr) / 2;
  return Math.abs(auc);
}

/* ---------- Logistic / softmax regression (real gradient descent) ---------- */
async function trainLogisticRegression(X, y, nClasses, { epochs = 60, lr = 0.15 } = {}, onProgress) {
  const n = X.length, d = X[0].length;
  let W = Array.from({ length: nClasses }, () => new Array(d).fill(0));
  let b = new Array(nClasses).fill(0);
  const scoresOf = (row) => W.map((w, c) => w.reduce((s, wi, j) => s + wi * row[j], 0) + b[c]);
  const softmax = (z) => { const m = Math.max(...z); const ex = z.map((v) => Math.exp(v - m)); const s = ex.reduce((a, v) => a + v, 0); return ex.map((v) => v / s); };
  const history = [];
  for (let e = 0; e < epochs; e++) {
    const gW = Array.from({ length: nClasses }, () => new Array(d).fill(0));
    const gB = new Array(nClasses).fill(0);
    let loss = 0;
    for (let i = 0; i < n; i++) {
      const p = softmax(scoresOf(X[i]));
      for (let c = 0; c < nClasses; c++) {
        const target = y[i] === c ? 1 : 0;
        const diff = p[c] - target;
        for (let j = 0; j < d; j++) gW[c][j] += diff * X[i][j];
        gB[c] += diff;
      }
      loss += -Math.log(Math.max(p[y[i]], 1e-9));
    }
    for (let c = 0; c < nClasses; c++) { for (let j = 0; j < d; j++) W[c][j] -= (lr * gW[c][j]) / n; b[c] -= (lr * gB[c]) / n; }
    loss /= n;
    const preds = X.map((row) => argmax(scoresOf(row)));
    const acc = accuracyScore(y, preds);
    history.push({ epoch: e + 1, loss, acc });
    if (onProgress) await onProgress({ epoch: e + 1, total: epochs, loss, acc });
    if (e % 4 === 0) await tick();
  }
  return {
    type: "logreg", history,
    predict: (Xn) => Xn.map((row) => argmax(scoresOf(row))),
    predictProba: (Xn) => Xn.map((row) => softmax(scoresOf(row))),
    importance: () => {
      const imp = new Array(d).fill(0);
      for (let c = 0; c < nClasses; c++) for (let j = 0; j < d; j++) imp[j] += Math.abs(W[c][j]);
      const tot = imp.reduce((a, v) => a + v, 0) || 1;
      return imp.map((v) => (v / tot) * 100);
    },
  };
}

/* ---------- Decision tree (CART, real recursive split-finding) ---------- */
function buildDecisionTree(X, y, opts = {}, rnd = Math.random) {
  const { maxDepth = 6, minSamplesSplit = 2, criterion = "gini", task = "classification", nClasses = 2, nFeaturesSample = null } = opts;
  const nFeatures = X[0].length;
  const importance = new Array(nFeatures).fill(0);

  function impurityFromCounts(counts, n) {
    if (criterion === "entropy") return -counts.reduce((s, c) => (c ? s + (c / n) * Math.log2(c / n) : s), 0);
    return 1 - counts.reduce((s, c) => s + (c / n) ** 2, 0);
  }
  function impurity(idxs) {
    if (task === "regression") { const vals = idxs.map((i) => y[i]); const m = mean(vals); return mean(vals.map((v) => (v - m) ** 2)); }
    const counts = new Array(nClasses).fill(0);
    idxs.forEach((i) => counts[y[i]]++);
    return impurityFromCounts(counts, idxs.length);
  }
  function leafValue(idxs) {
    if (task === "regression") return mean(idxs.map((i) => y[i]));
    const counts = new Array(nClasses).fill(0);
    idxs.forEach((i) => counts[y[i]]++);
    return argmax(counts);
  }
  function bestSplit(idxs, featureIdxs, parentImp) {
    let best = null;
    const total = idxs.length;
    for (const f of featureIdxs) {
      const sorted = idxs.slice().sort((a, b) => X[a][f] - X[b][f]);
      if (task === "regression") {
        let sumAll = 0, sumSqAll = 0;
        sorted.forEach((i) => { sumAll += y[i]; sumSqAll += y[i] * y[i]; });
        let sumLeft = 0, sumSqLeft = 0;
        for (let k = 0; k < sorted.length - 1; k++) {
          const yi = y[sorted[k]];
          sumLeft += yi; sumSqLeft += yi * yi;
          if (X[sorted[k]][f] === X[sorted[k + 1]][f]) continue;
          const nl = k + 1, nr = total - nl;
          const sumRight = sumAll - sumLeft, sumSqRight = sumSqAll - sumSqLeft;
          const varL = sumSqLeft / nl - (sumLeft / nl) ** 2;
          const varR = sumSqRight / nr - (sumRight / nr) ** 2;
          const weighted = (nl / total) * varL + (nr / total) * varR;
          const gain = parentImp - weighted;
          if (!best || gain > best.gain) {
            const thresh = (X[sorted[k]][f] + X[sorted[k + 1]][f]) / 2;
            best = { f, thresh, gain, leftIdx: sorted.slice(0, k + 1), rightIdx: sorted.slice(k + 1) };
          }
        }
      } else {
        const rightCounts = new Array(nClasses).fill(0);
        sorted.forEach((i) => rightCounts[y[i]]++);
        const leftCounts = new Array(nClasses).fill(0);
        for (let k = 0; k < sorted.length - 1; k++) {
          const c = y[sorted[k]];
          leftCounts[c]++; rightCounts[c]--;
          if (X[sorted[k]][f] === X[sorted[k + 1]][f]) continue;
          const nl = k + 1, nr = total - nl;
          const impL = impurityFromCounts(leftCounts, nl);
          const impR = impurityFromCounts(rightCounts, nr);
          const weighted = (nl / total) * impL + (nr / total) * impR;
          const gain = parentImp - weighted;
          if (!best || gain > best.gain) {
            const thresh = (X[sorted[k]][f] + X[sorted[k + 1]][f]) / 2;
            best = { f, thresh, gain, leftIdx: sorted.slice(0, k + 1), rightIdx: sorted.slice(k + 1) };
          }
        }
      }
    }
    return best;
  }
  function build(idxs, depth) {
    const parentImp = impurity(idxs);
    if (depth >= maxDepth || idxs.length < minSamplesSplit || parentImp === 0) return { leaf: true, value: leafValue(idxs) };
    let featureIdxs = [...Array(nFeatures).keys()];
    if (nFeaturesSample) featureIdxs = seededShuffle(featureIdxs, Math.floor(rnd() * 1e9)).slice(0, nFeaturesSample);
    const split = bestSplit(idxs, featureIdxs, parentImp);
    if (!split || split.gain <= 1e-9) return { leaf: true, value: leafValue(idxs) };
    importance[split.f] += split.gain * idxs.length;
    return { leaf: false, feature: split.f, threshold: split.thresh, left: build(split.leftIdx, depth + 1), right: build(split.rightIdx, depth + 1) };
  }
  const root = build([...Array(X.length).keys()], 0);
  function predictOne(row, node = root) { return node.leaf ? node.value : row[node.feature] <= node.threshold ? predictOne(row, node.left) : predictOne(row, node.right); }
  const totalImp = importance.reduce((a, v) => a + v, 0) || 1;
  return { type: "dtree", root, task, predict: (Xn) => Xn.map((r) => predictOne(r)), importance: () => importance.map((v) => (v / totalImp) * 100) };
}

/* ---------- Random forest (real bagging + feature subsampling) ---------- */
async function buildRandomForest(X, y, opts = {}, onProgress) {
  const { nTrees = 40, maxDepth = 8, minSamplesSplit = 2, bootstrap = true, criterion = "gini", task = "classification", nClasses = 2 } = opts;
  const n = X.length, d = X[0].length;
  const nFeaturesSample = task === "regression" ? Math.max(1, Math.round(d / 3)) : Math.max(1, Math.round(Math.sqrt(d)));
  const trees = [];
  const rnd = mulberry32(123);
  for (let t = 0; t < nTrees; t++) {
    let idxs;
    if (bootstrap) { idxs = []; for (let i = 0; i < n; i++) idxs.push(Math.floor(rnd() * n)); }
    else idxs = seededShuffle([...Array(n).keys()], Math.floor(rnd() * 1e9)).slice(0, Math.round(n * 0.8));
    const Xs = idxs.map((i) => X[i]), ys = idxs.map((i) => y[i]);
    const tree = buildDecisionTree(Xs, ys, { maxDepth, minSamplesSplit, criterion, task, nClasses, nFeaturesSample }, rnd);
    trees.push(tree);
    if (onProgress) await onProgress({ tree: t + 1, total: nTrees });
    if (t % 4 === 0) await tick();
  }
  function predict(Xn) {
    if (task === "regression") return Xn.map((row) => mean(trees.map((tr) => tr.predict([row])[0])));
    return Xn.map((row) => { const votes = new Array(nClasses).fill(0); trees.forEach((tr) => votes[tr.predict([row])[0]]++); return argmax(votes); });
  }
  function importance() {
    const agg = new Array(d).fill(0);
    trees.forEach((tr) => tr.importance().forEach((v, i) => (agg[i] += v)));
    const tot = agg.reduce((a, v) => a + v, 0) || 1;
    return agg.map((v) => (v / tot) * 100);
  }
  return { type: "rf", trees, task, predict, importance };
}

/* ---------- Gradient boosting (real additive regression trees) ---------- */
async function buildGradientBoosting(X, y, opts = {}, onProgress) {
  const { nEstimators = 30, learningRate = 0.15, maxDepth = 3, task = "classification", nClasses = 2 } = opts;
  const n = X.length, d = X[0].length;
  if (task === "regression") {
    const base = mean(y);
    let F = new Array(n).fill(base);
    const trees = [];
    for (let m = 0; m < nEstimators; m++) {
      const residual = y.map((v, i) => v - F[i]);
      const tree = buildDecisionTree(X, residual, { maxDepth, minSamplesSplit: 2, task: "regression" });
      const preds = tree.predict(X);
      F = F.map((f, i) => f + learningRate * preds[i]);
      trees.push(tree);
      if (onProgress) await onProgress({ round: m + 1, total: nEstimators, loss: mseFn(y, F) });
      if (m % 3 === 0) await tick();
    }
    return {
      type: "gb", task, trees, base, learningRate,
      predict: (Xn) => Xn.map((row) => { let f = base; trees.forEach((tr) => (f += learningRate * tr.predict([row])[0])); return f; }),
      importance: () => { const agg = new Array(d).fill(0); trees.forEach((tr) => tr.importance().forEach((v, i) => (agg[i] += v))); const tot = agg.reduce((a, v) => a + v, 0) || 1; return agg.map((v) => (v / tot) * 100); },
    };
  }
  const boosters = [];
  for (let c = 0; c < nClasses; c++) {
    const yc = y.map((v) => (v === c ? 1 : 0));
    const p0 = Math.min(0.999, Math.max(0.001, mean(yc)));
    let F = new Array(n).fill(Math.log(p0 / (1 - p0)));
    const trees = [];
    for (let m = 0; m < nEstimators; m++) {
      const p = F.map((f) => 1 / (1 + Math.exp(-f)));
      const grad = yc.map((v, i) => v - p[i]);
      const tree = buildDecisionTree(X, grad, { maxDepth, minSamplesSplit: 2, task: "regression" });
      const preds = tree.predict(X);
      F = F.map((f, i) => f + learningRate * preds[i]);
      trees.push(tree);
      if (onProgress) await onProgress({ round: m + 1, total: nEstimators, classIndex: c, classTotal: nClasses });
      if (m % 3 === 0) await tick();
    }
    boosters.push({ trees, base: Math.log(p0 / (1 - p0)) });
  }
  function scoreClass(row, c) { let f = boosters[c].base; boosters[c].trees.forEach((tr) => (f += learningRate * tr.predict([row])[0])); return f; }
  function predict(Xn) { return Xn.map((row) => argmax(boosters.map((_, c) => scoreClass(row, c)))); }
  function predictProba(Xn) {
    return Xn.map((row) => { const s = boosters.map((_, c) => 1 / (1 + Math.exp(-scoreClass(row, c)))); const tot = s.reduce((a, v) => a + v, 0) || 1; return s.map((v) => v / tot); });
  }
  function importance() {
    const agg = new Array(d).fill(0);
    boosters.forEach((b) => b.trees.forEach((tr) => tr.importance().forEach((v, i) => (agg[i] += v))));
    const tot = agg.reduce((a, v) => a + v, 0) || 1;
    return agg.map((v) => (v / tot) * 100);
  }
  return { type: "gb", task, boosters, predict, predictProba, importance };
}

/* ---------- Gaussian Naive Bayes (real per-class mean/variance) ---------- */
function trainNaiveBayes(X, y, nClasses) {
  const d = X[0].length;
  const stats = [], priors = [];
  for (let c = 0; c < nClasses; c++) {
    const idxs = []; y.forEach((v, i) => { if (v === c) idxs.push(i); });
    priors.push(idxs.length / y.length);
    const means = new Array(d), vars = new Array(d);
    for (let j = 0; j < d; j++) { const col = idxs.map((i) => X[i][j]); means[j] = mean(col); vars[j] = Math.max(variance(col), 1e-6); }
    stats.push({ means, vars });
  }
  const logGauss = (x, m, v) => -0.5 * Math.log(2 * Math.PI * v) - (x - m) ** 2 / (2 * v);
  function scoresOf(row) { return stats.map((s, c) => { let lp = Math.log(priors[c]); for (let j = 0; j < row.length; j++) lp += logGauss(row[j], s.means[j], s.vars[j]); return lp; }); }
  function importance() {
    const overallMeans = new Array(d).fill(0).map((_, j) => mean(X.map((r) => r[j])));
    const imp = new Array(d).fill(0);
    for (let j = 0; j < d; j++) { let between = 0; stats.forEach((s, c) => { between += priors[c] * (s.means[j] - overallMeans[j]) ** 2; }); imp[j] = between; }
    const tot = imp.reduce((a, v) => a + v, 0) || 1;
    return imp.map((v) => (v / tot) * 100);
  }
  return { type: "nb", predict: (Xn) => Xn.map((row) => argmax(scoresOf(row))), predictProba: (Xn) => Xn.map((row) => { const s = scoresOf(row); const m = Math.max(...s); const ex = s.map((v) => Math.exp(v - m)); const t = ex.reduce((a, v) => a + v, 0); return ex.map((v) => v / t); }), importance };
}

/* ---------- KNN (real distance search, no training phase) ---------- */
function trainKNN(X, y, { k = 5, metric = "euclidean", task = "classification" } = {}) {
  const dist = (a, b) => (metric === "manhattan" ? a.reduce((s, v, i) => s + Math.abs(v - b[i]), 0) : Math.sqrt(a.reduce((s, v, i) => s + (v - b[i]) ** 2, 0)));
  function predictOne(row) {
    const d = X.map((xi, i) => ({ d: dist(row, xi), y: y[i] })).sort((a, b) => a.d - b.d).slice(0, k);
    if (task === "regression") return mean(d.map((n) => n.y));
    const counts = {}; d.forEach((n) => (counts[n.y] = (counts[n.y] || 0) + 1));
    let best = d[0].y, bc = 0;
    for (const key in counts) if (counts[key] > bc) { bc = counts[key]; best = Number(key); }
    return best;
  }
  return { type: "knn", predict: (Xn) => Xn.map(predictOne) };
}

/* ---------- Linear / Ridge / Lasso / ElasticNet via real coordinate descent ---------- */
async function trainLinearModel(X, y, { alpha = 0, l1Ratio = 0, iterations = 150 } = {}, onProgress) {
  const n = X.length, d = X[0].length;
  let w = new Array(d).fill(0), b = mean(y);
  const colNormSq = new Array(d).fill(0).map((_, j) => X.reduce((s, row) => s + row[j] * row[j], 0));
  const predictRow = (row) => b + row.reduce((s, v, j) => s + v * w[j], 0);
  const softThresh = (z, gamma) => (z > gamma ? z - gamma : z < -gamma ? z + gamma : 0);
  for (let it = 0; it < iterations; it++) {
    b = mean(y.map((yi, i) => yi - (predictRow(X[i]) - b)));
    for (let j = 0; j < d; j++) {
      let rho = 0;
      for (let i = 0; i < n; i++) {
        const predWithoutJ = b + X[i].reduce((s, v, k) => (k === j ? s : s + v * w[k]), 0);
        rho += X[i][j] * (y[i] - predWithoutJ);
      }
      const l1 = alpha * l1Ratio * n, l2 = alpha * (1 - l1Ratio) * n;
      w[j] = softThresh(rho, l1) / (colNormSq[j] + l2 || 1);
    }
    if (onProgress && it % 5 === 0) await onProgress({ iter: it + 1, total: iterations, loss: mseFn(y, X.map(predictRow)) });
    if (it % 10 === 0) await tick();
  }
  return {
    type: "linreg", w, b,
    predict: (Xn) => Xn.map(predictRow),
    importance: () => { const tot = w.reduce((s, v) => s + Math.abs(v), 0) || 1; return w.map((v) => (Math.abs(v) / tot) * 100); },
  };
}

/* ---------- Linear SVM via Pegasos (real SGD hinge-loss) + RFF for non-linear kernels ---------- */
function randomFourierFeatures(X, { gamma = 0.5, D = 100, seed = 7 } = {}) {
  const d = X[0].length;
  const rnd = mulberry32(seed);
  const gauss = () => { let u = 0, v = 0; while (u === 0) u = rnd(); while (v === 0) v = rnd(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v); };
  const W = Array.from({ length: D }, () => Array.from({ length: d }, () => gauss() * Math.sqrt(2 * gamma)));
  const B = Array.from({ length: D }, () => rnd() * 2 * Math.PI);
  const transform = (row) => W.map((w, k) => Math.sqrt(2 / D) * Math.cos(w.reduce((s, wi, j) => s + wi * row[j], 0) + B[k]));
  return { transform, transformAll: (Xn) => Xn.map(transform) };
}
async function trainSVMBinary(X, y01, { epochs = 20, C = 1 } = {}, onProgress) {
  const yS = y01.map((v) => (v === 1 ? 1 : -1));
  const n = X.length, d = X[0].length;
  let w = new Array(d).fill(0), bias = 0;
  const lambda = 1 / (n * C);
  const rnd = mulberry32(11);
  let t = 0;
  for (let e = 0; e < epochs; e++) {
    const order = seededShuffle([...Array(n).keys()], Math.floor(rnd() * 1e9));
    for (const i of order) {
      t += 1;
      const eta = 1 / (lambda * t);
      const margin = yS[i] * (w.reduce((s, wj, j) => s + wj * X[i][j], 0) + bias);
      if (margin < 1) { for (let j = 0; j < d; j++) w[j] = (1 - eta * lambda) * w[j] + eta * yS[i] * X[i][j]; bias += eta * yS[i] * 0.05; }
      else for (let j = 0; j < d; j++) w[j] = (1 - eta * lambda) * w[j];
    }
    const preds = X.map((row) => (w.reduce((s, wj, j) => s + wj * row[j], 0) + bias >= 0 ? 1 : -1));
    if (onProgress) await onProgress({ epoch: e + 1, total: epochs, acc: accuracyScore(yS, preds) });
    await tick();
  }
  return { w, bias, decision: (row) => w.reduce((s, wj, j) => s + wj * row[j], 0) + bias };
}
async function trainSVM(X, y, { kernel = "linear", gamma = 0.5, C = 1, epochs = 20, nClasses = 2 } = {}, onProgress) {
  let rff = null, Xt = X;
  if (kernel !== "linear") { rff = randomFourierFeatures(X, { gamma, D: 100 }); Xt = rff.transformAll(X); }
  const binaries = [];
  for (let c = 0; c < nClasses; c++) {
    const y01 = y.map((v) => (v === c ? 1 : 0));
    const model = await trainSVMBinary(Xt, y01, { epochs, C }, async (p) => { if (onProgress) await onProgress({ ...p, classIndex: c, classTotal: nClasses }); });
    binaries.push(model);
  }
  const transform = (row) => (rff ? rff.transform(row) : row);
  function predict(Xn) { return Xn.map((row) => { const rt = transform(row); return argmax(binaries.map((b) => b.decision(rt))); }); }
  function predictProba(Xn) {
    return Xn.map((row) => { const rt = transform(row); const s = binaries.map((b) => 1 / (1 + Math.exp(-b.decision(rt)))); const tot = s.reduce((a, v) => a + v, 0) || 1; return s.map((v) => v / tot); });
  }
  function importance() {
    if (kernel !== "linear") return null;
    const d = X[0].length; const agg = new Array(d).fill(0);
    binaries.forEach((b) => b.w.forEach((wj, j) => (agg[j] += Math.abs(wj))));
    const tot = agg.reduce((a, v) => a + v, 0) || 1;
    return agg.map((v) => (v / tot) * 100);
  }
  return { type: "svm", kernel, predict, predictProba, importance };
}

/* ---------- KMeans (real Lloyd's algorithm) ---------- */
async function trainKMeans(X, { k = 3, maxIter = 20 } = {}, onProgress) {
  const n = X.length, d = X[0].length;
  const centroidIdx = seededShuffle([...Array(n).keys()], 42).slice(0, k);
  let centroids = centroidIdx.map((i) => X[i].slice());
  let labels = new Array(n).fill(0);
  let lastInertia = null;
  for (let iter = 0; iter < maxIter; iter++) {
    let inertia = 0;
    for (let i = 0; i < n; i++) {
      let bd = Infinity, bi = 0;
      for (let c = 0; c < k; c++) { let dist = 0; for (let j = 0; j < d; j++) dist += (X[i][j] - centroids[c][j]) ** 2; if (dist < bd) { bd = dist; bi = c; } }
      labels[i] = bi; inertia += bd;
    }
    const sums = Array.from({ length: k }, () => new Array(d).fill(0));
    const counts = new Array(k).fill(0);
    for (let i = 0; i < n; i++) { counts[labels[i]]++; for (let j = 0; j < d; j++) sums[labels[i]][j] += X[i][j]; }
    for (let c = 0; c < k; c++) if (counts[c] > 0) centroids[c] = sums[c].map((v) => v / counts[c]);
    if (onProgress) await onProgress({ iter: iter + 1, total: maxIter, inertia });
    await tick();
    if (lastInertia !== null && Math.abs(lastInertia - inertia) < 1e-6) { lastInertia = inertia; break; }
    lastInertia = inertia;
  }
  return { type: "kmeans", centroids, labels, inertia: lastInertia };
}

/* ---------- DBSCAN (real region queries) ---------- */
function trainDBSCAN(X, { eps = 1.0, minPts = 5 } = {}) {
  const n = X.length;
  const dist = (a, b) => Math.sqrt(a.reduce((s, v, i) => s + (v - b[i]) ** 2, 0));
  const labels = new Array(n).fill(-2);
  let clusterId = 0;
  const regionQuery = (i) => { const nb = []; for (let j = 0; j < n; j++) if (dist(X[i], X[j]) <= eps) nb.push(j); return nb; };
  for (let i = 0; i < n; i++) {
    if (labels[i] !== -2) continue;
    const neighbors = regionQuery(i);
    if (neighbors.length < minPts) { labels[i] = -1; continue; }
    labels[i] = clusterId;
    const queue = [...neighbors];
    while (queue.length) {
      const j = queue.shift();
      if (labels[j] === -1) labels[j] = clusterId;
      if (labels[j] !== -2) continue;
      labels[j] = clusterId;
      const jn = regionQuery(j);
      if (jn.length >= minPts) queue.push(...jn);
    }
    clusterId++;
  }
  return { type: "dbscan", labels, nClusters: clusterId };
}

/* ---------- Agglomerative clustering (real hierarchical merge, capped n) ---------- */
function trainAgglomerative(X, { nClusters = 3, linkage = "average" } = {}) {
  const n = X.length;
  let clusters = Array.from({ length: n }, (_, i) => [i]);
  const dist = (a, b) => Math.sqrt(a.reduce((s, v, i) => s + (v - b[i]) ** 2, 0));
  function clusterDist(c1, c2) {
    const vals = [];
    for (const i of c1) for (const j of c2) vals.push(dist(X[i], X[j]));
    if (linkage === "single") return Math.min(...vals);
    if (linkage === "complete") return Math.max(...vals);
    return mean(vals);
  }
  while (clusters.length > nClusters) {
    let bi = 0, bj = 1, bd = Infinity;
    for (let i = 0; i < clusters.length; i++) for (let j = i + 1; j < clusters.length; j++) { const dd = clusterDist(clusters[i], clusters[j]); if (dd < bd) { bd = dd; bi = i; bj = j; } }
    clusters[bi] = clusters[bi].concat(clusters[bj]);
    clusters.splice(bj, 1);
  }
  const labels = new Array(n).fill(0);
  clusters.forEach((c, ci) => c.forEach((i) => (labels[i] = ci)));
  return { type: "agglo", labels, clusters };
}

/* ---------- Generic permutation importance (works for any trained model) ---------- */
async function permutationImportance(model, Xtest, ytest, task, onProgress) {
  const preds = model.predict(Xtest);
  const base = task === "regression" ? r2Score(ytest, preds) : accuracyScore(ytest, preds);
  const d = Xtest[0].length;
  const importances = [];
  const rnd = mulberry32(55);
  for (let j = 0; j < d; j++) {
    const Xp = Xtest.map((r) => r.slice());
    const col = Xp.map((r) => r[j]);
    const shuffled = seededShuffle(col, Math.floor(rnd() * 1e9));
    Xp.forEach((r, i) => { r[j] = shuffled[i]; });
    const predsP = model.predict(Xp);
    const scoreP = task === "regression" ? r2Score(ytest, predsP) : accuracyScore(ytest, predsP);
    importances.push(Math.max(0, base - scoreP));
    if (onProgress) await onProgress({ feature: j + 1, total: d });
    await tick();
  }
  const tot = importances.reduce((a, v) => a + v, 0) || 1;
  return importances.map((v) => (v / tot) * 100);
}

/* ---------- Monte-Carlo Shapley-style approximation (real, simplified) ---------- */
async function approxShap(model, Xtest, backgroundRow, onProgress, samplesPerRow = 6) {
  const d = Xtest[0].length;
  const rnd = mulberry32(77);
  const contributions = new Array(d).fill(0);
  const testSample = Xtest.slice(0, Math.min(15, Xtest.length));
  function predictRow(row) {
    if (model.predictProba) { const p = model.predictProba([row])[0]; return p.reduce((s, v, i) => s + v * i, 0); }
    return model.predict([row])[0];
  }
  for (const row of testSample) {
    for (let rep = 0; rep < samplesPerRow; rep++) {
      const perm = seededShuffle([...Array(d).keys()], Math.floor(rnd() * 1e9));
      let current = backgroundRow.slice();
      let prevPred = predictRow(current);
      for (const f of perm) { current[f] = row[f]; const newPred = predictRow(current); contributions[f] += newPred - prevPred; prevPred = newPred; }
    }
    if (onProgress) await onProgress({});
    await tick();
  }
  const absSum = contributions.reduce((a, v) => a + Math.abs(v), 0) || 1;
  return contributions.map((v) => (Math.abs(v) / absSum) * 100);
}

/* ---------- Real PCA via power iteration (used for feature-selection preview) ---------- */
function pca2(X) {
  const n = X.length, d = X[0].length;
  const cov = Array.from({ length: d }, () => new Array(d).fill(0));
  for (let a = 0; a < d; a++) for (let b = 0; b < d; b++) { let s = 0; for (let i = 0; i < n; i++) s += X[i][a] * X[i][b]; cov[a][b] = s / (n - 1); }
  function powerIteration(matrix, exclude) {
    let v = new Array(matrix.length).fill(0).map((_, i) => Math.sin(i + 1));
    for (let iter = 0; iter < 150; iter++) {
      let nv = matrix.map((row) => row.reduce((s, val, j) => s + val * v[j], 0));
      if (exclude) { const dot = nv.reduce((s, val, i) => s + val * exclude[i], 0); nv = nv.map((val, i) => val - dot * exclude[i]); }
      const norm = Math.sqrt(nv.reduce((s, val) => s + val * val, 0)) || 1;
      v = nv.map((val) => val / norm);
    }
    const Av = matrix.map((row) => row.reduce((s, val, j) => s + val * v[j], 0));
    const eigenvalue = v.reduce((s, val, i) => s + val * Av[i], 0);
    return { vector: v, value: eigenvalue };
  }
  const pc1 = powerIteration(cov);
  const pc2 = powerIteration(cov, pc1.vector);
  const totalVar = cov.reduce((s, row, i) => s + row[i], 0) || 1;
  const projected = X.map((row) => [row.reduce((s, v, j) => s + v * pc1.vector[j], 0), row.reduce((s, v, j) => s + v * pc2.vector[j], 0)]);
  return { projected, explained: [pc1.value / totalVar, pc2.value / totalVar] };
}

/* ============================================================
   REAL CSV → DATASET BUILDER (used by the Upload page so any
   user-provided CSV can actually be trained on, not just the
   six built-in datasets)
   ============================================================ */
function inferColumnTypes(fields, records) {
  return fields.map((f) => {
    const vals = records.map((r) => r[f]).filter((v) => v !== null && v !== undefined && v !== "");
    const numericCount = vals.filter((v) => typeof v === "number" && Number.isFinite(v)).length;
    const isNumeric = vals.length > 0 && numericCount / vals.length >= 0.85;
    return { name: f, type: isNumeric ? "float64" : "category" };
  });
}
function buildDatasetFromCSV(records, fields, targetField, label) {
  const MAX_ROWS = 3000;
  let recs = records;
  let subsampled = false;
  if (recs.length > MAX_ROWS) { recs = seededShuffle(recs, 1).slice(0, MAX_ROWS); subsampled = true; }

  const colTypes = inferColumnTypes(fields, recs);
  const typeByName = Object.fromEntries(colTypes.map((c) => [c.name, c.type]));
  const isMissing = (v) => v === null || v === undefined || v === "";

  const missing = {};
  const imputeValue = {};
  const catUniques = {};
  fields.forEach((f) => {
    const raw = recs.map((r) => r[f]);
    const missingCount = raw.filter(isMissing).length;
    if (missingCount > 0) missing[f] = missingCount;
    if (typeByName[f] === "float64") {
      const nums = raw.filter((v) => typeof v === "number" && Number.isFinite(v));
      imputeValue[f] = nums.length ? median(nums) : 0;
    } else {
      const strs = raw.filter((v) => !isMissing(v)).map(String);
      imputeValue[f] = strs.length ? modeOf(strs) : "unknown";
      catUniques[f] = [...new Set(raw.map((v) => (isMissing(v) ? imputeValue[f] : String(v))))].sort();
    }
  });

  const featureFields = fields.filter((f) => f !== targetField);
  const targetType = typeByName[targetField];
  const targetRaw = recs.map((r) => (isMissing(r[targetField]) ? imputeValue[targetField] : r[targetField]));

  let task, classes = null, encodeTarget;
  if (targetType === "float64") {
    const uniqueVals = [...new Set(targetRaw.map((v) => +v))];
    if (uniqueVals.length <= 15) { task = "classification"; classes = uniqueVals.sort((a, b) => a - b).map(String); encodeTarget = (v) => classes.indexOf(String(+v)); }
    else { task = "regression"; encodeTarget = (v) => +v; }
  } else {
    task = "classification";
    classes = catUniques[targetField] || [...new Set(targetRaw.map(String))].sort();
    encodeTarget = (v) => classes.indexOf(String(v));
  }

  function encodeFeatureValue(f, v) {
    const val = isMissing(v) ? imputeValue[f] : v;
    if (typeByName[f] === "float64") return +val;
    return catUniques[f].indexOf(String(val));
  }

  const rows = recs.map((r) => {
    const feats = featureFields.map((f) => encodeFeatureValue(f, r[f]));
    const t = encodeTarget(isMissing(r[targetField]) ? imputeValue[targetField] : r[targetField]);
    return [...feats, t];
  });

  const seen = new Set();
  let duplicates = 0;
  rows.forEach((row) => { const key = row.join(","); if (seen.has(key)) duplicates++; else seen.add(key); });

  const displayRows = recs.slice(0, 12).map((r) => fields.map((f) => (isMissing(r[f]) ? null : r[f])));
  const columns = fields.map((f) => ({ name: f, type: f === targetField && task === "classification" ? "category" : typeByName[f] }));

  return { label, icon: "📄", task, columns, features: featureFields, target: targetField, classes, rows, displayRows, missing, duplicates, subsampled, custom: true };
}

