const fadeUp = { hidden: { opacity: 0, y: 16 }, show: (i = 0) => ({ opacity: 1, y: 0, transition: { delay: i * 0.05, duration: 0.4, ease: [0.16, 1, 0.3, 1] } }) };

function GlassCard({ children, className = "", style = {}, hover = true, ...rest }) {
  return <div className={`glass-card ${hover ? "glass-hover" : ""} ${className}`} style={style} {...rest}>{children}</div>;
}
function Pill({ children, tone = "violet" }) {
  const tones = {
    violet: { bg: "rgba(99,102,241,0.14)", fg: COLORS.violet, bd: "rgba(99,102,241,0.3)" },
    cyan: { bg: "rgba(14,165,233,0.12)", fg: COLORS.cyan, bd: "rgba(14,165,233,0.3)" },
    amber: { bg: "rgba(255,176,32,0.14)", fg: COLORS.amber, bd: "rgba(255,176,32,0.3)" },
    rose: { bg: "rgba(255,107,139,0.14)", fg: COLORS.rose, bd: "rgba(255,107,139,0.3)" },
    green: { bg: "rgba(61,220,151,0.14)", fg: COLORS.green, bd: "rgba(61,220,151,0.3)" },
  };
  const t = tones[tone];
  return <span className="pill" style={{ background: t.bg, color: t.fg, border: `1px solid ${t.bd}` }}>{children}</span>;
}
function AnimatedNumber({ value, decimals = 0, suffix = "" }) {
  const [display, setDisplay] = useState(0);
  useEffect(() => {
    let raf; const start = performance.now(); const duration = 700; const to = value;
    function step(now) { const p = Math.min(1, (now - start) / duration); setDisplay(to * (1 - Math.pow(1 - p, 3))); if (p < 1) raf = requestAnimationFrame(step); }
    raf = requestAnimationFrame(step);
    return () => cancelAnimationFrame(raf);
  }, [value]);
  return <span>{display.toLocaleString(undefined, { maximumFractionDigits: decimals, minimumFractionDigits: decimals })}{suffix}</span>;
}
function StatCard({ icon: Icon, label, value, decimals = 0, suffix = "", tone = "violet", i = 0, text, onClick }) {
  return (
    <motion.div variants={fadeUp} initial="hidden" animate="show" custom={i}>
      <GlassCard className={`stat-card ${onClick ? "clickable" : ""}`} onClick={onClick} role={onClick ? "button" : undefined} tabIndex={onClick ? 0 : undefined}>
        <div className="stat-card-top"><div className={`icon-badge tone-${tone}`}><Icon size={17} /></div>{onClick && <ChevronRight size={13} className="stat-card-chev" />}</div>
        <div className="stat-value">{text !== undefined ? text : <AnimatedNumber value={value} decimals={decimals} suffix={suffix} />}</div>
        <div className="stat-label">{label}</div>
      </GlassCard>
    </motion.div>
  );
}
