function downloadFile(filename, content, type = "text/plain") {
  const blob = new Blob([content], { type });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a"); a.href = url; a.download = filename; document.body.appendChild(a); a.click(); a.remove();
  URL.revokeObjectURL(url);
}
function DigitImage({ pixels, size = 8, px = 4 }) {
  const max = 16;
  return (
    <svg width={size * px} height={size * px} style={{ borderRadius: 4, background: "#0c0d13" }}>
      {pixels.map((v, i) => { const r = Math.floor(i / size), c = i % size; const t = Math.min(1, v / max); return <rect key={i} x={c * px} y={r * px} width={px} height={px} fill={`rgba(99,102,241,${t})`} />; })}
    </svg>
  );
}
function Heatmap({ matrix }) {
  const { cols, values } = matrix;
  const colorFor = (v) => (v >= 0 ? `rgba(99,102,241,${Math.min(1, Math.abs(v)) * 0.85 + 0.1})` : `rgba(255,107,139,${Math.min(1, Math.abs(v)) * 0.85 + 0.1})`);
  return (
    <div className="heatmap">
      <div className="heatmap-grid" style={{ gridTemplateColumns: `70px repeat(${cols.length}, 1fr)` }}>
        <div />
        {cols.map((c) => <div key={c} className="heatmap-label">{c.slice(0, 7)}</div>)}
        {values.map((row, i) => (
          <React.Fragment key={i}>
            <div className="heatmap-label">{cols[i].slice(0, 9)}</div>
            {row.map((v, j) => <div key={j} className="heatmap-cell" style={{ background: colorFor(v) }} title={`${cols[i]} × ${cols[j]}: ${v.toFixed(2)}`}>{v.toFixed(2)}</div>)}
          </React.Fragment>
        ))}
      </div>
    </div>
  );
}
function BoxPlot({ data }) {
  const max = Math.max(...data.map((d) => d.high)) || 1;
  const min = Math.min(...data.map((d) => d.low));
  const range = max - min || 1;
  return (
    <div className="boxplot">
      {data.map((d) => (
        <div className="boxplot-col" key={d.name}>
          <div className="boxplot-track" style={{ height: 160 }}>
            <div className="boxplot-whisker" style={{ bottom: `${((d.low - min) / range) * 100}%`, height: `${((d.high - d.low) / range) * 100}%` }} />
            <div className="boxplot-box" style={{ bottom: `${((d.q1 - min) / range) * 100}%`, height: `${((d.q3 - d.q1) / range) * 100}%` }}>
              <div className="boxplot-median" style={{ bottom: `${((d.med - d.q1) / (d.q3 - d.q1 || 1)) * 100}%` }} />
            </div>
          </div>
          <div className="boxplot-label">{d.name.slice(0, 9)}</div>
        </div>
      ))}
    </div>
  );
}
function PreviewTable({ columns, rows }) {
  return (
    <div className="table-wrap">
      <table className="data-table">
        <thead><tr>{columns.map((c) => <th key={c.name}>{c.name}</th>)}</tr></thead>
        <tbody>{rows.map((row, i) => <tr key={i}>{row.map((cell, j) => <td key={j}>{cell === null || cell === undefined ? <span className="null-cell">NaN</span> : String(cell)}</td>)}</tr>)}</tbody>
      </table>
    </div>
  );
}

